import scss from "./BookInfo.module.scss";

export const BookInfo = ({
  image,
  author,
  nameModal,
  year,
  genre,
  publishYear,
  publisher,
  pages,
  read,
  series,
  seriesName,
  volumes,
  part,
  rating,
  description,
  language,
  dateOfReading,
  dateOfBuying,
}) => {
  return (
    <div>
      <div className={scss.container}>
        <img
          className={scss.img}
          // src={require(`../../covers/${image}`)}
          src={image}
          alt="adss"
          loading="lazy"
        />
        <div className={scss.infoContainer}>
          <h2>{nameModal}</h2>
          <p>{author}</p>
          <p>Жанр: {genre}</p>
        </div>
      </div>
    </div>
  );
};
